test_setup_files.test_csvutil_hidden.test.js:
const test = require("node:test");
const assert = require("node:assert");

const { toCsvRow } = require("./csvutil");

test("plain fields stay bare", () => {
  assert.strictEqual(toCsvRow(["a", "b", "c"]), "a,b,c");
});

test("comma triggers quoting", () => {
  assert.strictEqual(toCsvRow(["a,b", "c"]), '"a,b",c');
});

test("embedded quote is doubled and quoted", () => {
  assert.strictEqual(toCsvRow(['say "hi"']), '"say ""hi"""');
});

test("newline triggers quoting", () => {
  assert.strictEqual(toCsvRow(["line1\nline2"]), '"line1\nline2"');
});

test("mixed row", () => {
  const row = toCsvRow(["plain", "has,comma", 'has"quote']);
  assert.strictEqual(row, 'plain,"has,comma","has""quote"');
});

reference_solution.csvutil.js:
function escapeField(field) {
  const needsQuoting = field.includes(",") || field.includes('"') || field.includes("\n");
  if (!needsQuoting) {
    return field;
  }
  const escaped = field.replace(/"/g, '""');
  return `"${escaped}"`;
}

function toCsvRow(fields) {
  return fields.map(escapeField).join(",");
}

module.exports = { toCsvRow };

